<?php
session_start(); if(!isset($_SESSION['admin_id'])){header('Location: ../login.php');exit;}
require_once __DIR__.'/../../fastfood/database.php';
$pdo->exec("UPDATE orders SET delivery_status=COALESCE(delivery_status,'new') WHERE order_type='delivery' AND delivery_status IS NULL");
if($_SERVER['REQUEST_METHOD']==='POST'){
 $order=(int)($_POST['order_id']??0); $action=$_POST['action']??'';
 if($action==='assign'){$cid=(int)$_POST['courier_id'];$pdo->prepare("UPDATE orders SET courier_id=?,delivery_status='assigned',status='yetkazilmoqda' WHERE id=? AND order_type='delivery'")->execute([$cid,$order]);}
 if($action==='status'){$st=$_POST['delivery_status'];$allowed=['new','assigned','picked_up','on_the_way','delivered','cancelled'];if(in_array($st,$allowed,true)){$pdo->prepare("UPDATE orders SET delivery_status=?, status=? WHERE id=? AND order_type='delivery'")->execute([$st,$st==='delivered'?'yakunlangan':($st==='cancelled'?'bekor qilingan':'yetkazilmoqda'),$order]);}}
 header('Location: index.php');exit;
}
$couriers=$pdo->query("SELECT * FROM delivery_couriers ORDER BY status DESC,name")->fetchAll();
$orders=$pdo->query("SELECT o.*,c.name courier_name,c.phone courier_phone,c.current_lat,c.current_lng,c.location_updated_at FROM orders o LEFT JOIN delivery_couriers c ON c.id=o.courier_id WHERE o.order_type='delivery' ORDER BY o.created_at DESC LIMIT 100")->fetchAll();
?>
