</head><body><?php include __DIR__.'/../sidebar.php'; ?><main class="delivery-admin"><div class="delivery-hero"><div><div style="color:#9b2c3a;font-weight:900;letter-spacing:.12em">DELIVERY CENTER</div><h1>🛵 Dostavka</h1><p style="color:var(--muted,#777)">Buyurtmalar, kuryerlar va GPS lokatsiyalarni boshqaring.</p></div><a class="btn btn-secondary" href="index.php">↻ Yangilash</a></div><div class="delivery-grid"><section class="delivery-card"><h2>Faol dostavkalar</h2><?php foreach($orders as $o): $st=$o['delivery_status']?:'new'; ?><article class="delivery-row"><div class="delivery-row-top"><div><b>#<?= $o['id'] ?> — <?=htmlspecialchars($o['customer_name'])?></b><div class="meta"><span>📞 <?=htmlspecialchars($o['phone'])?></span><span>💰 <?=number_format($o['total'],0,'',' ')?> so‘m</span><span><?=htmlspecialchars($o['created_at'])?></span></div></div><span class="badge"><?=htmlspecialchars($st)?></span></div><div style="margin:8px 0"><b>📍 <?=htmlspecialchars($o['address'])?></b><?php if($o['courier_id'] && isset($o['current_lat']) && $o['current_lat']): ?><div class="meta">🛵 Kuryer GPS: <?=htmlspecialchars($o['current_lat'])?>, <?=htmlspecialchars($o['current_lng'])?><?php if($o['location_updated_at']): ?> · <?=htmlspecialchars($o['location_updated_at'])?><?php endif; ?></div><?php endif; ?><?php if($o['delivery_lat'] && $o['delivery_lng']): ?><div><a class="map-link" target="_blank" href="https://www.openstreetmap.org/?mlat=<?=htmlspecialchars($o['delivery_lat'])?>&mlon=<?=htmlspecialchars($o['delivery_lng'])?>#map=18/<?=htmlspecialchars($o['delivery_lat'])?>/<?=htmlspecialchars($o['delivery_lng'])?>">🗺️ GPS xaritada ochish</a></div><?php endif; ?></div><div class="delivery-actions"><form method="post"><input type="hidden" name="order_id" value="<?=$o['id']?>"><input type="hidden" name="action" value="assign"><select name="courier_id"><option value="">Kuryer tanlang</option><?php foreach($couriers as $c): ?><option value="<?=$c['id']?>" <?=$o['courier_id']==$c['id']?'selected':''?>><?=htmlspecialchars($c['name'])?> — <?=htmlspecialchars($c['vehicle']??'')?></option><?php endforeach; ?></select><button class="btn btn-sm" type="submit">Biriktirish</button></form><form method="post"><input type="hidden" name="order_id" value="<?=$o['id']?>"><input type="hidden" name="action" value="status"><select name="delivery_status" onchange="this.form.submit()"><?php foreach(['new'=>'Yangi','assigned'=>'Kuryer biriktirildi','picked_up'=>'Buyurtma olindi','on_the_way'=>'Yo‘lda','delivered'=>'Yetkazildi','cancelled'=>'Bekor qilindi'] as $k=>$v): ?><option value="<?=$k?>" <?=$st===$k?'selected':''?>><?=$v?></option><?php endforeach; ?></select></form></div></article><?php endforeach; if(!$orders): ?><p style="color:var(--muted,#777)">Dostavka buyurtmalari yo‘q.</p><?php endif; ?></section><aside class="delivery-card"><h2>👨‍✈️ Kuryerlar</h2><?php foreach($couriers as $c): ?><div class="courier"><b><?=htmlspecialchars($c['name'])?></b><span><?=htmlspecialchars($c['phone'])?></span><span class="<?=htmlspecialchars($c['status'])?>">● <?=htmlspecialchars($c['status'])?></span><small><?=htmlspecialchars($c['vehicle']??'')?></small></div><?php endforeach; ?></aside></div></main><script src="../../js/lang-switch.js"></script><script src="../../js/lang-switch.js"></script><script src="../../js/universal-i18n.js"></script></body></html>
